import { test, expect } from '@playwright/test';

test.describe('Faceted Search - Real-time Results Update', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should update search results in real-time as user filters by category', async ({ page }) => {
    // Verify initial search results are displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify initial result count
    const resultCount = page.getByText(/10 results/i);
    await expect(resultCount).toBeVisible();

    // Verify initial result items
    const resultItems = page.locator('[data-testid="search-result-item"]');
    await expect(resultItems).toHaveCount(10);

    // Apply category filter using getByRole
    const categoryFilter = page.getByRole('button', { name: /filter by category/i });
    await categoryFilter.click();

    // Verify category filter appears
    await expect(categoryFilter).toBeVisible();

    // Verify category options are displayed
    const categoryOptions = page.locator('[data-testid="category-option"]');
    await expect(categoryOptions).toHaveCount(3);

    // Select a category using getByRole
    const categoryOption = page.getByRole('option', { name: /books/i });
    await categoryOption.click();

    // Verify category filter is applied
    await expect(categoryFilter).toContainText('books');

    // Verify results are filtered by category
    await expect(resultItems).toHaveCount(5);

    // Verify category name is displayed
    const categoryName = page.getByText(/books/i);
    await expect(categoryName).toBeVisible();

    // Verify results are still visible
    await expect(resultsContainer).toBeVisible();

    // Verify search results are updated in real-time
    await page.waitForTimeout(100);
    await expect(resultItems).toHaveCount(5);

    // Verify category filter is still active
    await expect(categoryFilter).toBeVisible();

    // Verify category options are still displayed
    await expect(categoryOptions).toHaveCount(3);

    // Verify category name is still displayed
    await expect(categoryName).toBeVisible();

    // Verify results are still visible
    await expect(resultsContainer).toBeVisible();
  });

  test('should handle empty search results gracefully when no items match filters', async ({ page }) => {
    // Apply multiple filters using getByRole
    const categoryFilter = page.getByRole('button', { name: /filter by category/i });
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /books/i });
    await categoryOption.click();

    const priceRangeFilter = page.getByRole('button', { name: /price range/i });
    await priceRangeFilter.click();

    const priceRangeOption = page.getByRole('option', { name: /$100-$200/i });
    await priceRangeOption.click();

    // Verify no results are displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    const resultCount = page.getByText(/0 results/i);
    await expect(resultCount).toBeVisible();

    // Verify no result items are displayed
    const resultItems = page.locator('[data-testid="search-result-item"]');
    await expect(resultItems).not.toHaveCount(1);

    // Verify category and price range filters are still visible
    await expect(categoryFilter).toBeVisible();
    await expect(priceRangeFilter).toBeVisible();

    // Verify category options are still displayed
    await expect(categoryOptions).toHaveCount(3);

    // Verify category name is still displayed
    const categoryName = page.getByText(/books/i);
    await expect(categoryName).toBeVisible();

    // Verify results container is still visible
    await expect(resultsContainer).toBeVisible();

    // Verify no results are displayed
    await expect(resultItems).not.toHaveCount(1);
  });
});
